import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The plans of a sheet's people. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class PlanController {

    /**
     * A plan as shown: its amount with two decimals, its dates as yyyy-mm-dd, its interval in days or its day of the
     * month (the other null), and how many claims it has made.
     */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, long generated) {

        static PlanView of(Plan plan, long generated) {
            return new PlanView(plan.getId(), plan.getPersonId(),
                    plan.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), generated);
        }
    }

    /**
     * An amount with up to two decimals, a start and end date, and either the interval in whole days or the day of the
     * month (the other blank or left out).
     */
    public record PlanRequest(
            @NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            @NotNull LocalDate start,
            @Pattern(regexp = "\\s*(\\d{1,6})?\\s*") String every,
            @Pattern(regexp = "\\s*(\\d{1,6})?\\s*") String day,
            @NotNull LocalDate end) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }

        Integer everyValue() {
            return whole(every);
        }

        Integer dayValue() {
            return whole(day);
        }

        private static Integer whole(String text) {
            return text == null || text.isBlank() ? null : Integer.valueOf(text.trim());
        }
    }

    /** How many claims a generate made. */
    public record GenerateResult(int made) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping("/plans")
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, Long> generated = service.generatedCounts(sheetId.trim());
        return service.list(sheetId.trim()).stream()
                .map(plan -> PlanView.of(plan, generated.getOrDefault(plan.getId(), 0L)))
                .toList();
    }

    @PostMapping("/people/{personId}/plans")
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PlanRequest request) {
        return PlanView.of(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.start(),
                request.everyValue(), request.dayValue(), request.end()), 0);
    }

    /** Make the claims of every plan date due and not yet made. */
    @PostMapping("/plans/generate")
    public GenerateResult generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new GenerateResult(service.generate(sheetId.trim(), user.trim()));
    }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, signal } from '@angular/core';
import { Plans } from '../../core/plans';

/** An amount with at most two decimals, more than 0.00. */
const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;
/** A date typed as yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;
/** A whole number of days. */
const WHOLE = /^\d{1,6}$/;

// A person's plans, and the form on their row that adds one.
@Component({
  selector: 'app-person-plans',
  template: `
    <ul [attr.aria-label]="'Plans of ' + personName()">
      @for (pl of plans(); track pl.id) {
        <li [attr.data-testid]="'plan-row-' + pl.id">
          {{ pl.amount }} from {{ pl.start }}
          @if (pl.day !== null) { monthly on day {{ pl.day }} } @else { every {{ pl.every }} days }
          to {{ pl.end }};
          made <span data-testid="plan-generated">{{ pl.generated }}</span>
        </li>
      }
    </ul>
    <form (submit)="add($event)" [attr.aria-label]="'Add a plan for ' + personName()">
      <label [for]="'plan-form-amount-' + personId()" class="visually-hidden">Plan amount</label>
      <input
        [id]="'plan-form-amount-' + personId()"
        data-testid="plan-form-amount"
        placeholder="Amount"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-start-' + personId()" class="visually-hidden">Plan start</label>
      <input
        [id]="'plan-form-start-' + personId()"
        type="date"
        data-testid="plan-form-start"
        [value]="start()"
        (input)="start.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-every-' + personId()" class="visually-hidden">Every how many days</label>
      <input
        [id]="'plan-form-every-' + personId()"
        data-testid="plan-form-every"
        placeholder="Every N days"
        [value]="every()"
        (input)="every.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-day-' + personId()" class="visually-hidden">Or monthly on day of the month</label>
      <input
        [id]="'plan-form-day-' + personId()"
        data-testid="plan-form-day"
        placeholder="Or day of month"
        [value]="day()"
        (input)="day.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-end-' + personId()" class="visually-hidden">Plan end</label>
      <input
        [id]="'plan-form-end-' + personId()"
        type="date"
        data-testid="plan-form-end"
        [value]="end()"
        (input)="end.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="plan-form-submit">Add plan</button>
      @if (error(); as message) {
        <p role="alert" data-testid="plan-error">{{ message }}</p>
      }
    </form>
  `,
})
export class PersonPlans {
  private readonly store = inject(Plans);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();

  protected readonly plans = computed(() => this.store.list().filter((p) => p.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly start = signal('');
  protected readonly every = signal('');
  protected readonly day = signal('');
  protected readonly end = signal('');
  protected readonly error = signal<string | null>(null);
  /** Whether an add is waiting for its answer: a second add meanwhile is ignored. */
  private adding = false;

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async add(event: Event): Promise<void> {
    event.preventDefault();
    if (this.adding) return;
    this.error.set(null);
    const plan = {
      amount: this.amount().trim(),
      start: this.start().trim(),
      every: this.every().trim(),
      day: this.day().trim(),
      end: this.end().trim(),
    };
    if (!AMOUNT.test(plan.amount) || Number(plan.amount) <= 0) {
      this.error.set('Type an amount more than 0.00 with at most two decimals.');
      return;
    }
    if (!DATE.test(plan.start) || !DATE.test(plan.end)) {
      this.error.set('Type the start and end as yyyy-mm-dd.');
      return;
    }
    if ((plan.every === '') === (plan.day === '')) {
      this.error.set('Type either every how many days or a day of the month, not both.');
      return;
    }
    if (plan.every !== '' && (!WHOLE.test(plan.every) || Number(plan.every) < 1)) {
      this.error.set('Type every how many days as a whole number, at least 1.');
      return;
    }
    if (plan.day !== '' && (!WHOLE.test(plan.day) || Number(plan.day) < 1 || Number(plan.day) > 31)) {
      this.error.set('Type the day of the month as a whole number from 1 to 31.');
      return;
    }
    if (plan.end < plan.start) {
      this.error.set('The end may not be before the start.');
      return;
    }
    this.adding = true;
    try {
      await this.store.add(this.personId(), plan);
      this.amount.set('');
      this.start.set('');
      this.every.set('');
      this.day.set('');
      this.end.set('');
    } catch (e) {
      const detail = e instanceof HttpErrorResponse && typeof e.error?.message === 'string' ? ` ${e.error.message}` : '';
      this.error.set('The plan could not be added.' + detail);
    } finally {
      this.adding = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/**
 * A person's plan: a claim of the amount on the start date, then every so many days, up to the end date; or, run
 * monthly, on a day of each month from the start's month (the month's last day when it is shorter).
 */
export interface PlanView {
  id: number;
  personId: number;
  /** Two decimals, e.g. "2.50". */
  amount: string;
  start: string;
  /** Every so many days, or null when the plan runs monthly. */
  every: number | null;
  /** The day of the month (1 to 31) a monthly plan runs on, or null. */
  day: number | null;
  end: string;
  /** How many claims the plan has made so far. */
  generated: number;
}

// The active sheet's plans, in the order they were added, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly list = signal<PlanView[]>([]);
  private reads = 0;

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loaded();
      untracked(() => {
        this.list.set([]);
        if (sheet) void this.read(sheet);
      });
    });
  }

  /** Add a plan to the person on the active sheet; throws when the store refuses it. */
  async add(personId: number, plan: { amount: string; start: string; every: string; day: string; end: string }): Promise<void> {
    const sheet = this.session.sheet();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<PlanView>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/plans`,
        plan,
        this.session.headers(),
      ),
    );
    if (this.session.sheet() === sheet) this.list.update((list) => [...list, saved]);
  }

  /** Make the DRAFT claims of every plan date due and not yet made: how many were made; throws when refused. */
  async generate(): Promise<number> {
    const sheet = this.session.sheet();
    if (!sheet) throw new Error('No sheet loaded.');
    const result = await firstValueFrom(
      this.http.post<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/plans/generate`,
        null,
        this.session.headers(),
      ),
    );
    await this.read(sheet);
    return result.made;
  }

  private async read(sheet: string): Promise<void> {
    const read = ++this.reads;
    const list = await firstValueFrom(
      this.http.get<PlanView[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`, this.session.headers()),
    ).catch(() => null);
    // A later read wins over a slower earlier one.
    if (list && read === this.reads && this.session.sheet() === sheet) {
      this.list.set(list);
    }
  }
}

